import{_ as e,c as r,o as i,af as t}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"7、【师】 坎下坤上","description":"温公易说 - 7、【师】 坎下坤上","frontmatter":{"title":"7、【师】 坎下坤上","description":"温公易说 - 7、【师】 坎下坤上"},"headers":[],"relativePath":"zh/classics/wengong/008.md","filePath":"zh/classics/wengong/008.md"}'),h={name:"zh/classics/wengong/008.md"};function n(l,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_7、【师】-坎下坤上" tabindex="-1">7、【师】 坎下坤上 <a class="header-anchor" href="#_7、【师】-坎下坤上" aria-label="Permalink to “7、【师】 坎下坤上”">​</a></h1><p>师：贞，丈人吉，无咎。何也？曰：难之也。夫治众，天下之大事也，非圣人则不能。夫众之所服者，武也；所从者，智也；所亲者，仁也。三者不备而能用其众，未之有也。然或得之小，或得之大；或用之邪，或用之正。邪正大小之道，其得失吉凶相去远矣。彼小人者，以矫矫为武，瞲瞲为智，喣喣为仁，众人亦有悦而从之者，所谓小也。圣人者，以正人为武，安人为智，利人为仁，天下皆悦而从之，所谓大也。夫小人之得众也，以为上则以为下，则乱，故谓之邪。圣人之得众也，所以禁而止乱也，故谓之正。夫众非小人之所用也，小人用之以为不正，咎孰大焉。</p><p>子罕曰：兵者，所以威不轨而昭文德也。圣人以兴，乱人以废，此之谓也。</p><h3 id="彖曰-师众也-贞正也。能以众正-可以王矣。刚中而应-行险而顺-以此毒天下而民从之-吉又何咎矣。王者-何大人之谓也-刚中而应-行险而顺者-治众而不以刚则慢而不振-用刚而不获中则暴而无亲。上无应于君-下无应于民-则身危而功不成。所施不在于顺-则众怒而民不从。四者非所以吉而无咎也。吉而无咎-则惟刚中而应-行险而顺者乎-夫兵者-危事也-故曰行险。财用之蠹-而民之残也-故曰毒天下。毒之者-其志将以安之也-若针砭之所以已疾也-是以民从而无咎也。" tabindex="-1">彖曰：师众也，贞正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣。王者，何大人之谓也？刚中而应，行险而顺者，治众而不以刚则慢而不振，用刚而不获中则暴而无亲。上无应于君，下无应于民，则身危而功不成。所施不在于顺，则众怒而民不从。四者非所以吉而无咎也。吉而无咎，则惟刚中而应，行险而顺者乎？夫兵者，危事也，故曰行险。财用之蠹，而民之残也，故曰毒天下。毒之者，其志将以安之也，若针砭之所以已疾也，是以民从而无咎也。 <a class="header-anchor" href="#彖曰-师众也-贞正也。能以众正-可以王矣。刚中而应-行险而顺-以此毒天下而民从之-吉又何咎矣。王者-何大人之谓也-刚中而应-行险而顺者-治众而不以刚则慢而不振-用刚而不获中则暴而无亲。上无应于君-下无应于民-则身危而功不成。所施不在于顺-则众怒而民不从。四者非所以吉而无咎也。吉而无咎-则惟刚中而应-行险而顺者乎-夫兵者-危事也-故曰行险。财用之蠹-而民之残也-故曰毒天下。毒之者-其志将以安之也-若针砭之所以已疾也-是以民从而无咎也。" aria-label="Permalink to “彖曰：师众也，贞正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣。王者，何大人之谓也？刚中而应，行险而顺者，治众而不以刚则慢而不振，用刚而不获中则暴而无亲。上无应于君，下无应于民，则身危而功不成。所施不在于顺，则众怒而民不从。四者非所以吉而无咎也。吉而无咎，则惟刚中而应，行险而顺者乎？夫兵者，危事也，故曰行险。财用之蠹，而民之残也，故曰毒天下。毒之者，其志将以安之也，若针砭之所以已疾也，是以民从而无咎也。”">​</a></h3><h3 id="象曰-地中有水-师。君子以容民畜众。" tabindex="-1">象曰：地中有水，师。君子以容民畜众。 <a class="header-anchor" href="#象曰-地中有水-师。君子以容民畜众。" aria-label="Permalink to “象曰：地中有水，师。君子以容民畜众。”">​</a></h3><p>师之所以为容民畜众者，非特施于治兵之谓也。故天子用之以治天下，诸侯用之以治其国，卿大夫用之以治其家，其道一也。</p><h3 id="初六-师出以律-否臧凶。-象曰-师出以律-失律凶也。" tabindex="-1">初六：师出以律，否臧凶。 象曰：师出以律，失律凶也。 <a class="header-anchor" href="#初六-师出以律-否臧凶。-象曰-师出以律-失律凶也。" aria-label="Permalink to “初六：师出以律，否臧凶。 象曰：师出以律，失律凶也。”">​</a></h3><h3 id="九二-在师中-吉无咎-王三锡命。-象曰-在师中-吉承天宠也。王三锡命-怀万邦也。" tabindex="-1">九二：在师中，吉无咎，王三锡命。 象曰：在师中，吉承天宠也。王三锡命，怀万邦也。 <a class="header-anchor" href="#九二-在师中-吉无咎-王三锡命。-象曰-在师中-吉承天宠也。王三锡命-怀万邦也。" aria-label="Permalink to “九二：在师中，吉无咎，王三锡命。 象曰：在师中，吉承天宠也。王三锡命，怀万邦也。”">​</a></h3><h3 id="六三-师或舆尸-凶。-象曰-师或舆尸-大无功也。" tabindex="-1">六三：师或舆尸，凶。 象曰：师或舆尸，大无功也。 <a class="header-anchor" href="#六三-师或舆尸-凶。-象曰-师或舆尸-大无功也。" aria-label="Permalink to “六三：师或舆尸，凶。 象曰：师或舆尸，大无功也。”">​</a></h3><h3 id="六四-师左次-无咎。-象曰-左次无咎-未失常也。" tabindex="-1">六四：师左次，无咎。 象曰：左次无咎，未失常也。 <a class="header-anchor" href="#六四-师左次-无咎。-象曰-左次无咎-未失常也。" aria-label="Permalink to “六四：师左次，无咎。 象曰：左次无咎，未失常也。”">​</a></h3><h3 id="六五-田有禽-利执言-无咎。长子帅师-弟子舆尸-贞凶。-象曰-长子帅师-以中行也。弟子舆尸-使不当也。" tabindex="-1">六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。 象曰：长子帅师，以中行也。弟子舆尸，使不当也。 <a class="header-anchor" href="#六五-田有禽-利执言-无咎。长子帅师-弟子舆尸-贞凶。-象曰-长子帅师-以中行也。弟子舆尸-使不当也。" aria-label="Permalink to “六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。 象曰：长子帅师，以中行也。弟子舆尸，使不当也。”">​</a></h3><p>师六五柔也，其为师之主奈何？古者人君之遣将也，跪而推毂曰：&quot;阃以内，寡人制之；阃以外，将军制之。&quot;进止之制，赏罚之权，皆决于外，不从中覆也。委任责成功而已矣。六五以柔居尊，下应于二，二以刚中能任其事，是以动则有功，若田狩而获禽也。师出无名，事故不成，故曰利执言。执者何？奉辞伐罪之谓也。举国家之众而委之一人，此安危之机，存亡之端，不可以不谨。谨择其人，是人君之事守也。故曰长子帅师，弟子舆尸，贞凶者，虽正犹凶也。</p><h3 id="上六-大君有命-开国承家-小人勿用。-象曰-大君有命-以正功也。小人勿用-必乱邦也。" tabindex="-1">上六：大君有命，开国承家，小人勿用。 象曰：大君有命，以正功也。小人勿用，必乱邦也。 <a class="header-anchor" href="#上六-大君有命-开国承家-小人勿用。-象曰-大君有命-以正功也。小人勿用-必乱邦也。" aria-label="Permalink to “上六：大君有命，开国承家，小人勿用。 象曰：大君有命，以正功也。小人勿用，必乱邦也。”">​</a></h3>',13)])])}const b=e(h,[["render",n]]);export{p as __pageData,b as default};
